import{_ as a,o as s,c as n,a0 as o}from"./chunks/framework.C3yZ6M33.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),t={name:"explanation/architecture.md"};function r(i,e,p,c,d,l){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Peregrin is the <em>policy</em> layer for coding-agent sessions and workflows: who may act on a session, when, and on which machine — plus the orchestration plane (campaigns, drivers, events, transport) on top. Session <em>mechanism</em> — attach, prompt, restore, per-agent stores — lives in <a href="https://9aia.com/sepia/" target="_blank" rel="noreferrer">sepia</a>, which peregrin consumes over a subprocess wire rather than by linking internals.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌─────────────── peregrin-hub ───────────────┐</span></span>
<span class="line"><span>                 │  aggregation · sync · arbitration · web UI  │</span></span>
<span class="line"><span>                 └──────────────┬───────────────┬─────────────┘</span></span>
<span class="line"><span>                        HTTP+SSE │               │ HTTP+SSE</span></span>
<span class="line"><span>                  ┌──────────────▼──┐    ┌───────▼──────────┐</span></span>
<span class="line"><span>                  │ peregrin-node A │    │ peregrin-node B  │</span></span>
<span class="line"><span>                  │  /api/* surface │    │  /api/* surface  │</span></span>
<span class="line"><span>                  └───────┬─────────┘    └────────┬─────────┘</span></span>
<span class="line"><span>                  spawn + │ ndjson JSON-RPC       │</span></span>
<span class="line"><span>                  ┌───────▼─────────┐    ┌────────▼─────────┐</span></span>
<span class="line"><span>                  │   sepia serve   │    │   sepia serve    │</span></span>
<span class="line"><span>                  │  session plane  │    │  session plane   │</span></span>
<span class="line"><span>                  └─────────────────┘    └──────────────────┘</span></span></code></pre></div><h2 id="mechanism-vs-policy" tabindex="-1">Mechanism vs policy <a class="header-anchor" href="#mechanism-vs-policy" aria-label="Permalink to &quot;Mechanism vs policy&quot;">​</a></h2><p>The split is deliberate: sepia does things <em>to</em> sessions; peregrin decides <em>who/when/where</em>. Concretely — <code>peregrin-control</code> holds the lock registry, takeover arbitration, and <code>pick_owner</code> routing; the hub consults it before forwarding; nodes report lock state up. Anything that mutates a session (prompt, attach, rewind) flows down to sepia with the policy decision already made.</p><h2 id="the-sepia-boundary" tabindex="-1">The sepia boundary <a class="header-anchor" href="#the-sepia-boundary" aria-label="Permalink to &quot;The sepia boundary&quot;">​</a></h2><p>A node never links <code>sepia-session</code> into orchestration code. It spawns <code>sepia serve</code> and drives it over ndjson JSON-RPC stdio — the same framing sepia&#39;s own store drivers speak — via <code>peregrin-session::ServicePlane</code>. An in-process <code>LocalPlane</code> remains selectable for dev (<code>PEREGRIN_SESSION_PLANE=local</code>/<code>inprocess</code>); both implement the same <code>SessionPlane</code> trait, so <code>peregrin-http</code> and everything above it is blind to which side of the fork it&#39;s on. The manifest handshake negotiates protocol versions at spawn.</p><h2 id="planes" tabindex="-1">Planes <a class="header-anchor" href="#planes" aria-label="Permalink to &quot;Planes&quot;">​</a></h2><ul><li><strong>Session plane</strong> — the sepia surface: sessions, agents, attach, prompts, events. Nodes own it; the hub proxies it.</li><li><strong>Orchestration plane</strong> — peregrin&#39;s own: campaigns (declarative workflows over agents via <code>peregrin-engine</code> + loaders + templates), the event bus, remote transport, and the outbox for offline ordering.</li><li><strong>App plane</strong> — <code>peregrin-http</code>/<code>peregrin-web</code>: REST + SSE, the Leptos UI, node-local overlay state (<code>PEREGRIN_META</code> — pins, archives, run spans; node-owned, not part of the session wire).</li></ul><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p>Policy crates are pure; every I/O seam is a port (<code>peregrin-{store,bus,remote,config,secret,service,loader,template}</code>) with impls behind it (<code>-toml</code>, <code>-http</code>, <code>-yaml</code>, <code>-keyring</code>, <code>-dotenv</code>, <code>-systemd</code>). Engine semantics are documented in <code>project/adrs/</code> — read those before changing campaign behaviour.</p>`,11)])])}const g=a(t,[["render",r]]);export{m as __pageData,g as default};
